      ${ev.development ? `<h3 style="font-size:13px;font-weight:700;color:${textD};margin:0 0 8px">Development</h3><p style="font-size:13px;color:${textM};line-height:1.7;margin:0 0 16px">${ev.development}</p>` : ''}
